(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,17477,e=>{e.v(JSON.parse('[{"id":"q001","tier":"free","category":"tactical","scenario":{"ja":"暗闘の廃墟。銃声が止んだ。\\n味方は2人ダウン。敵は1人、どこかに潜んでいる。\\n弾は残り5発。\\n静寂の中、お前の次の一手が全てを決める。","en":"A ruined building, shrouded in darkness. Gunfire has ceased.\\nTwo allies are down. One enemy lurks somewhere.\\nFive rounds left.\\nIn the silence, your next move decides everything."},"options":[{"id":"a","text":{"ja":"走り込む。奇襲で仕留める。","en":"Rush in. Take them by surprise."},"scores":{"aggression":15,"altruism":-5,"cooperation":-10,"intuition":10,"mastery":-5}},{"id":"b","text":{"ja":"味方を蘇生しに行く。数の有利を取る。","en":"Revive allies first. Gain numerical advantage."},"scores":{"aggression":-10,"altruism":15,"cooperation":15,"intuition":-5,"mastery":5}},{"id":"c","text":{"ja":"音を聞く。敵の位置を特定してから動く。","en":"Listen. Locate the enemy before moving."},"scores":{"aggression":-15,"altruism":0,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"d","text":{"ja":"撤退する。生き残ることが最優先。","en":"Retreat. Survival is the priority."},"scores":{"aggression":-10,"altruism":-10,"cooperation":-5,"intuition":5,"mastery":-10}}]},{"id":"q002","tier":"free","category":"social","scenario":{"ja":"ランクマッチ。味方のひとりがVCで暴言を吐き続けている。\\n「お前のせいで負けたんだよ」\\nチーム全体の士気が下がっていく。\\nお前はどうする。","en":"Ranked match. One teammate won\'t stop flaming on voice chat.\\n\\"We lost because of you.\\"\\nTeam morale is plummeting.\\nWhat do you do."},"options":[{"id":"a","text":{"ja":"正面から言い返す。間違いは正す。","en":"Call them out directly. Wrong is wrong."},"scores":{"aggression":10,"altruism":5,"cooperation":-5,"intuition":10,"mastery":10}},{"id":"b","text":{"ja":"ミュートして無視。自分のプレイに集中する。","en":"Mute and ignore. Focus on your own play."},"scores":{"aggression":-5,"altruism":-10,"cooperation":-15,"intuition":-5,"mastery":10}},{"id":"c","text":{"ja":"チームを落ち着かせようとする。空気を変える。","en":"Try to calm the team. Change the mood."},"scores":{"aggression":-10,"altruism":15,"cooperation":15,"intuition":5,"mastery":-5}},{"id":"d","text":{"ja":"黙って実力で黙らせる。結果が全て。","en":"Say nothing. Let your performance speak."},"scores":{"aggression":5,"altruism":-5,"cooperation":-10,"intuition":-10,"mastery":15}}]},{"id":"q003","tier":"free","category":"meta","scenario":{"ja":"新作ゲームが2本、同時に発売された。\\nひとつは、誰もが話題にしている超大作。もうひとつは、知る人ぞ知るインディーの傑作。\\nお金は1本分しかない。\\nどちらを手に取る。","en":"Two new games released on the same day.\\nOne is the blockbuster everyone\'s talking about. The other is a critically acclaimed indie gem.\\nYou can only afford one.\\nWhich do you pick up."},"options":[{"id":"a","text":{"ja":"超大作。みんなとプレイしたい。","en":"The blockbuster. I want to play with everyone."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"インディー。自分だけの体験が欲しい。","en":"The indie gem. I want my own unique experience."},"scores":{"aggression":0,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"レビューを読み込んでから決める。","en":"Read reviews extensively, then decide."},"scores":{"aggression":-5,"altruism":0,"cooperation":0,"intuition":-15,"mastery":5}},{"id":"d","text":{"ja":"セール待ち。今は積みゲーを崩す。","en":"Wait for a sale. Clear the backlog first."},"scores":{"aggression":-10,"altruism":0,"cooperation":0,"intuition":-5,"mastery":-15}}]},{"id":"q004","tier":"free","category":"tactical","scenario":{"ja":"最終ラウンド。スコアは同点。\\n残り時間30秒。お前のチームは防衛側。\\n敵は一斉に攻めてくる気配がある。\\nお前はスナイパー。高台からエリア全体が見える。","en":"Final round. Score is tied.\\n30 seconds left. Your team is on defense.\\nThe enemy is about to rush.\\nYou\'re the sniper. You overlook the entire area from the high ground."},"options":[{"id":"a","text":{"ja":"高台を捨てて前に出る。敵の裏を取る。","en":"Leave the high ground. Flank the enemy."},"scores":{"aggression":15,"altruism":-5,"cooperation":-10,"intuition":15,"mastery":-5}},{"id":"b","text":{"ja":"高台に留まる。一発一発を確実に当てる。","en":"Hold position. Make every shot count."},"scores":{"aggression":-5,"altruism":0,"cooperation":5,"intuition":-15,"mastery":15}},{"id":"c","text":{"ja":"味方にカバーの指示を出しながら援護する。","en":"Call out positions and provide cover fire for allies."},"scores":{"aggression":-5,"altruism":10,"cooperation":15,"intuition":-5,"mastery":5}},{"id":"d","text":{"ja":"武器を持ち替える。近距離戦に備える。","en":"Switch weapons. Prepare for close combat."},"scores":{"aggression":10,"altruism":-5,"cooperation":-5,"intuition":10,"mastery":-10}}]},{"id":"q005","tier":"free","category":"social","scenario":{"ja":"チームの仲間が、大事な大会の前に脱退を告げてきた。\\n「リアルが忙しくて、もう続けられない」\\nお前はチームリーダーだ。大会まであと3日。\\n代わりのメンバーを探す時間はギリギリある。","en":"A clan member announces they\'re leaving, right before a major tournament.\\n\\"Real life got too busy. I can\'t continue.\\"\\nYou\'re the clan leader. Three days until the tournament.\\nThere\'s barely enough time to find a replacement."},"options":[{"id":"a","text":{"ja":"引き止める。最後まで責任を果たせ。","en":"Convince them to stay. Finish what you started."},"scores":{"aggression":10,"altruism":-5,"cooperation":10,"intuition":5,"mastery":10}},{"id":"b","text":{"ja":"快く送り出す。人生の方が大事だ。","en":"Let them go gracefully. Life comes first."},"scores":{"aggression":-15,"altruism":15,"cooperation":5,"intuition":5,"mastery":-10}},{"id":"c","text":{"ja":"すぐに代わりを探し始める。感情は後。","en":"Immediately start looking for a replacement. Emotions later."},"scores":{"aggression":5,"altruism":-10,"cooperation":5,"intuition":-10,"mastery":-5}},{"id":"d","text":{"ja":"4人で出る。少数精鋭で戦う。","en":"Enter with 4. Fight as an elite few."},"scores":{"aggression":10,"altruism":0,"cooperation":-15,"intuition":15,"mastery":15}}]},{"id":"q010","tier":"free","category":"meta","scenario":{"ja":"深夜3時。明日は大事な用事がある。\\nでも今、ゲームが最高に楽しい。\\n「あと1試合だけ」を3回言った。\\n画面の光だけが、暗い部屋を照らしている。","en":"3 AM. You have something important tomorrow.\\nBut the game is hitting different right now.\\nYou\'ve said \'just one more match\' three times.\\nThe screen\'s glow is the only light in the dark room."},"options":[{"id":"a","text":{"ja":"もう1試合。後悔は明日の俺に任せる。","en":"One more. Future me can deal with the consequences."},"scores":{"aggression":10,"altruism":-10,"cooperation":0,"intuition":15,"mastery":-15}},{"id":"b","text":{"ja":"やめる。自制心がプレイヤーとしての格。","en":"Stop. Self-discipline defines a true player."},"scores":{"aggression":-15,"altruism":5,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"アラームをセットして、あと30分だけ。","en":"Set an alarm. 30 more minutes, no exceptions."},"scores":{"aggression":0,"altruism":0,"cooperation":0,"intuition":-5,"mastery":5}},{"id":"d","text":{"ja":"明日の用事をキャンセルする。今この瞬間が大事。","en":"Cancel tomorrow\'s plans. This moment matters more."},"scores":{"aggression":15,"altruism":-15,"cooperation":-5,"intuition":15,"mastery":-10}}]},{"id":"q012","tier":"free","category":"tactical","scenario":{"ja":"チーム戦。序盤から優勢。\\n自分の担当エリアでは敵を圧倒している。\\nだが隣のエリアの味方がボコボコにされている。\\n助けに行けば自分のエリアが手薄になる。","en":"MOBA. Early laning phase.\\nYou\'ve scored two kills and have a level advantage.\\nYour teammate in the next lane is getting destroyed.\\nBut if you roam now, you might lose your own tower."},"options":[{"id":"a","text":{"ja":"助けに行く。チーム全体が大事。","en":"Roam and help. The team matters most."},"scores":{"aggression":0,"altruism":15,"cooperation":15,"intuition":15,"mastery":0}},{"id":"b","text":{"ja":"自分のエリアを攻め続ける。ここを制圧する方が価値がある。","en":"Keep pushing your lane. Taking the tower is worth more."},"scores":{"aggression":-15,"altruism":-5,"cooperation":-15,"intuition":-15,"mastery":-15}},{"id":"c","text":{"ja":"警告だけ出す。判断は味方に任せる。","en":"Ping a warning. Whether they listen is on them."},"scores":{"aggression":0,"altruism":-5,"cooperation":5,"intuition":-15,"mastery":-5}},{"id":"d","text":{"ja":"敵の裏側に回り込む。別の角度から圧力をかける。","en":"Invade their jungle. Apply pressure from behind."},"scores":{"aggression":-5,"altruism":-15,"cooperation":0,"intuition":15,"mastery":-10}}]},{"id":"q013","tier":"free","category":"tactical","scenario":{"ja":"サバイバルホラー。弾薬はショットガン2発だけ。\\n暗い廊下の先に、セーブルームがある。\\nでもその途中に、何かがいる気配がする。\\n迂回路はある。ただし3倍の距離。","en":"Survival horror. Two shotgun shells left.\\nA save room lies at the end of this dark corridor.\\nBut something lurks between you and it.\\nThere\'s a detour. Three times the distance."},"options":[{"id":"a","text":{"ja":"直進する。2発あれば十分。","en":"Go straight. Two shells is enough."},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"迂回する。弾薬は温存すべき。","en":"Take the detour. Conserve ammunition."},"scores":{"aggression":-5,"altruism":15,"cooperation":10,"intuition":-10,"mastery":-5}},{"id":"c","text":{"ja":"ナイフに切り替える。弾は最後の手段。","en":"Switch to the knife. Save bullets for emergencies."},"scores":{"aggression":5,"altruism":-5,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"d","text":{"ja":"物を投げて様子を見る。敵の数を確認する。","en":"Throw something. Scout how many are out there."},"scores":{"aggression":-5,"altruism":15,"cooperation":-5,"intuition":-15,"mastery":10}}]},{"id":"q014","tier":"free","category":"tactical","scenario":{"ja":"ステルスゲーム。潜入ミッション。\\n目標の部屋まであと少し。だが警備員が2人、巡回ルートを変えた。\\nこのまま行けば見つかる確率が高い。\\n屋上からのルートがあるが、時間がかかる。","en":"Stealth game. Infiltration mission.\\nAlmost at the target room. But two guards just changed their patrol route.\\nGoing forward means high chance of detection.\\nThere\'s a rooftop route, but it\'ll cost time."},"options":[{"id":"a","text":{"ja":"2人とも倒す。見つかっても構わない。","en":"Take them both out. Detection doesn\'t matter."},"scores":{"aggression":15,"altruism":0,"cooperation":0,"intuition":10,"mastery":-10}},{"id":"b","text":{"ja":"タイミングを計って間をすり抜ける。","en":"Time their patterns and slip through the gap."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"屋上ルートを取る。確実性が全て。","en":"Take the rooftop. Certainty above all."},"scores":{"aggression":-15,"altruism":5,"cooperation":5,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"陽動を仕掛ける。注意を逸らして突破する。","en":"Create a distraction. Draw their attention, then move."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":15,"mastery":-5}}]},{"id":"q016","tier":"free","category":"tactical","scenario":{"ja":"大人数のボス戦。8人のチーム。ボスの体力は残り5%。\\nチームの盾役（敵の攻撃を引き受ける役）が倒れた。控えの盾役も体力半分。\\nお前は回復役。味方を復活させるのに3秒かかる。\\nその3秒で、控えの盾役も倒れるかもしれない。","en":"MMO raid. Eight-player party. Boss at 5% HP.\\nMain tank is down. Off-tank at half health.\\nYou\'re the healer. Resurrection takes 3 seconds.\\nIn those 3 seconds, the off-tank might fall too."},"options":[{"id":"a","text":{"ja":"盾役を復活させる。正攻法で行く。","en":"Resurrect the main tank. Do it by the book."},"scores":{"aggression":-15,"altruism":15,"cooperation":-15,"intuition":-15,"mastery":5}},{"id":"b","text":{"ja":"控えの盾役を全力回復。今いる人を生かす。","en":"Full heal the off-tank. Keep the living alive."},"scores":{"aggression":-10,"altruism":0,"cooperation":5,"intuition":0,"mastery":-5}},{"id":"c","text":{"ja":"攻撃魔法に切り替える。残り5%なら押し切れる。","en":"Switch to damage spells. At 5%, just burn it down."},"scores":{"aggression":0,"altruism":-10,"cooperation":-15,"intuition":15,"mastery":10}},{"id":"d","text":{"ja":"全体にバリアを張る。時間を稼ぐ。","en":"Cast a party-wide shield. Buy time for everyone."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":-10,"mastery":10}}]},{"id":"q017","tier":"free","category":"tactical","scenario":{"ja":"レースゲーム。最終ラップ。2位。\\n1位との差は0.8秒。普通に走れば追いつけない。\\nショートカットがある。ただしミスれば崖に落ちる。\\n3位は遥か後方。最低でも表彰台は確定している。","en":"Racing game. Final lap. Second place.\\n0.8 seconds behind first. Normal driving won\'t close the gap.\\nThere\'s a shortcut. Miss it and you fly off a cliff.\\nThird place is far behind. A podium finish is guaranteed."},"options":[{"id":"a","text":{"ja":"ショートカットを攻める。1位以外に意味はない。","en":"Take the shortcut. First or nothing."},"scores":{"aggression":15,"altruism":-5,"cooperation":-15,"intuition":5,"mastery":-5}},{"id":"b","text":{"ja":"2位を守る。確実なポイントを取る。","en":"Secure second. Take the guaranteed points."},"scores":{"aggression":-15,"altruism":15,"cooperation":15,"intuition":-5,"mastery":-5}},{"id":"c","text":{"ja":"コーナーで限界まで攻める。技術で0.8秒を縮める。","en":"Push every corner to the limit. Close 0.8 seconds with pure skill."},"scores":{"aggression":15,"altruism":5,"cooperation":-15,"intuition":-15,"mastery":10}},{"id":"d","text":{"ja":"1位の後ろにぴったりつく。最終コーナーで勝負する。","en":"Draft behind first. Make your move at the final corner."},"scores":{"aggression":10,"altruism":10,"cooperation":-10,"intuition":15,"mastery":-15}}]},{"id":"q019","tier":"free","category":"tactical","scenario":{"ja":"FPS。爆弾解除ミッション。残り15秒。\\n爆弾の前に敵が1人張り付いている。\\n味方は後ろから来ているが、間に合うか微妙。\\nフラッシュバンが1個残っている。","en":"FPS. Bomb defusal. 15 seconds left.\\nOne enemy is planted on the bomb.\\nYour teammate is rotating in, but might not make it.\\nYou have one flashbang left."},"options":[{"id":"a","text":{"ja":"フラッシュバンを投げて突入。一人で解決する。","en":"Flash and push. Handle it alone."},"scores":{"aggression":0,"altruism":-10,"cooperation":-10,"intuition":15,"mastery":15}},{"id":"b","text":{"ja":"味方を待つ。2人で挟む。","en":"Wait for backup. Pinch them from both sides."},"scores":{"aggression":-10,"altruism":15,"cooperation":5,"intuition":-15,"mastery":0}},{"id":"c","text":{"ja":"フェイクを入れる。敵に反応させてから撃つ。","en":"Fake a peek. Bait their reaction, then fire."},"scores":{"aggression":-5,"altruism":-10,"cooperation":5,"intuition":5,"mastery":-5}},{"id":"d","text":{"ja":"別角度から回り込む。予想外の方向から仕掛ける。","en":"Rotate to an unexpected angle. Hit them where they don\'t expect."},"scores":{"aggression":5,"altruism":5,"cooperation":0,"intuition":0,"mastery":0}}]},{"id":"q021","tier":"free","category":"tactical","scenario":{"ja":"サバイバルゲーム。3日目の夜。\\n拠点の壁が一部壊れている。敵の襲撃は今夜来る。\\n修理する資材はあるが、武器の弾薬製造にも使える。\\n両方に十分な量はない。","en":"Survival game. Night three.\\nPart of your base wall is broken. An enemy raid is coming tonight.\\nYou have materials to repair it—or to craft ammunition.\\nNot enough for both."},"options":[{"id":"a","text":{"ja":"弾薬を作る。攻撃が最大の防御。","en":"Craft ammo. Offense is the best defense."},"scores":{"aggression":15,"altruism":10,"cooperation":-15,"intuition":15,"mastery":0}},{"id":"b","text":{"ja":"壁を修理する。拠点を守ることが最優先。","en":"Repair the wall. Protecting the base comes first."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":-5,"mastery":10}},{"id":"c","text":{"ja":"壊れた壁をトラップに変える。侵入させて罠にかける。","en":"Turn the breach into a kill zone. Let them in—into a trap."},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-5}},{"id":"d","text":{"ja":"拠点を捨てて移動する。執着しない。","en":"Abandon the base and relocate. Don\'t get attached."},"scores":{"aggression":-15,"altruism":-10,"cooperation":-15,"intuition":0,"mastery":-5}}]},{"id":"q022","tier":"free","category":"tactical","scenario":{"ja":"チーム戦。5対5の総力戦。\\nお前の必殺技は全体に大ダメージを与えるが、発動に2秒かかる。\\n味方の防御役が敵を引きつけている。でも持って3秒。\\n使うなら今しかない。でも最高のタイミングはまだ先かもしれない。","en":"MOBA. Full 5v5 teamfight.\\nYour ultimate deals massive AoE damage but takes 2 seconds to charge.\\nYour tank is holding the enemy. They\'ll last maybe 3 seconds.\\nUse it now, or wait for the perfect moment that may never come."},"options":[{"id":"a","text":{"ja":"今すぐ撃つ。迷ったら負ける。","en":"Fire now. Hesitation is defeat."},"scores":{"aggression":10,"altruism":-5,"cooperation":5,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"1秒だけ待つ。敵が固まった瞬間を狙う。","en":"Wait one second. Aim for the moment they cluster."},"scores":{"aggression":5,"altruism":5,"cooperation":0,"intuition":-5,"mastery":15}},{"id":"c","text":{"ja":"味方に「あいつを集中攻撃」と指示してから撃つ。","en":"Call the target first, then fire."},"scores":{"aggression":-10,"altruism":15,"cooperation":10,"intuition":5,"mastery":10}},{"id":"d","text":{"ja":"温存する。この集団戦は味方に任せて次に備える。","en":"Hold it. Let the team handle this one—save it for next."},"scores":{"aggression":-15,"altruism":-10,"cooperation":-5,"intuition":-10,"mastery":0}}]},{"id":"q024","tier":"free","category":"tactical","scenario":{"ja":"ダンジョンRPG。パーティで迷宮を探索中。\\n分かれ道。左は宝箱のマーク。右はボスの気配。\\nMPが半分しか残っていない。帰還アイテムは1個。\\n宝箱にはレアアイテムがあるかもしれない。","en":"Dungeon RPG. Exploring with your party.\\nA fork in the road. Left shows a treasure marker. Right feels like a boss.\\nMP at half. One return item remaining.\\nThe chest might hold something rare."},"options":[{"id":"a","text":{"ja":"ボスに直行。宝は後で取りに来る。","en":"Head for the boss. Come back for treasure later."},"scores":{"aggression":15,"altruism":-15,"cooperation":-10,"intuition":5,"mastery":15}},{"id":"b","text":{"ja":"宝箱を先に開ける。装備次第でボスが楽になる。","en":"Open the chest first. Better gear might make the boss easier."},"scores":{"aggression":-5,"altruism":10,"cooperation":5,"intuition":-15,"mastery":-15}},{"id":"c","text":{"ja":"一度帰還する。万全の状態で両方攻略する。","en":"Return to town. Clear both at full strength."},"scores":{"aggression":-15,"altruism":15,"cooperation":10,"intuition":-10,"mastery":0}},{"id":"d","text":{"ja":"パーティを2つに分ける。同時に攻略する。","en":"Split the party. Tackle both at once."},"scores":{"aggression":15,"altruism":-15,"cooperation":-5,"intuition":15,"mastery":-10}}]},{"id":"q025","tier":"free","category":"tactical","scenario":{"ja":"バトロワ。ストームが迫っている。\\n目の前に物資が大量に落ちている建物。\\nだが建物の中に敵がいるのは確実。\\nストームに飲まれるまで40秒。迂回すれば安全だが手ぶら。","en":"Battle royale. The storm is closing.\\nA building stuffed with loot sits ahead.\\nEnemies are definitely inside.\\n40 seconds before the storm swallows you. Detour is safe but you\'ll have nothing."},"options":[{"id":"a","text":{"ja":"突入する。物資も敵のキルも全部取る。","en":"Storm the building. Take the loot and the kills."},"scores":{"aggression":5,"altruism":0,"cooperation":0,"intuition":-10,"mastery":5}},{"id":"b","text":{"ja":"迂回する。装備は道中で拾う。","en":"Take the detour. Scavenge on the way."},"scores":{"aggression":-10,"altruism":5,"cooperation":0,"intuition":-10,"mastery":-15}},{"id":"c","text":{"ja":"建物の外から投げ物で炙り出す。","en":"Flush them out with grenades from outside."},"scores":{"aggression":15,"altruism":-5,"cooperation":15,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"ストームのギリギリを走って、出てきた敵を狩る。","en":"Ride the storm edge and pick off anyone who flees."},"scores":{"aggression":-15,"altruism":-10,"cooperation":0,"intuition":15,"mastery":-5}}]},{"id":"q027","tier":"free","category":"social","scenario":{"ja":"ゲームコミュニティの幹部ミーティング。方針で意見が割れている。\\n攻略重視派と交流重視派。どちらも正しい。\\nお前は副リーダー。最終判断を求められている。\\nどちらを選んでも、誰かが不満を持つ。","en":"Guild officers\' meeting. The guild is split.\\nHardcore raiders vs. casual community builders. Both have a point.\\nYou\'re the vice guild master. The final call falls on you.\\nEither way, someone will be unhappy."},"options":[{"id":"a","text":{"ja":"攻略重視。結果がなければ人は離れる。","en":"Prioritize progression. Without results, people leave anyway."},"scores":{"aggression":10,"altruism":-15,"cooperation":-5,"intuition":-10,"mastery":15}},{"id":"b","text":{"ja":"交流重視。居心地のいい場所が長続きする。","en":"Prioritize community. A welcoming place lasts longer."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"両立させる仕組みを提案する。グループ分けする。","en":"Propose a system for both. Create separate groups."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"投票にかける。みんなで決めるのが民主主義。","en":"Put it to a vote. Let democracy decide."},"scores":{"aggression":-5,"altruism":5,"cooperation":15,"intuition":0,"mastery":-15}}]},{"id":"q029","tier":"free","category":"social","scenario":{"ja":"配信をしていたら、視聴者が「そのプレイ下手すぎ」とコメントした。\\n同時視聴者は200人。みんなが反応を見ている。\\nコメントした相手はチャットの常連。\\n普段は応援してくれている人だ。","en":"You\'re streaming. A viewer comments: \\"That play was terrible.\\"\\n200 concurrent viewers. Everyone is watching your reaction.\\nThe commenter is a regular in your chat.\\nUsually, they\'re supportive."},"options":[{"id":"a","text":{"ja":"笑い飛ばす。「確かにひどかったw」","en":"Laugh it off. \\"Yeah, that was pretty bad lol.\\""},"scores":{"aggression":15,"altruism":10,"cooperation":15,"intuition":0,"mastery":-15}},{"id":"b","text":{"ja":"スルーする。いちいち反応しない。","en":"Ignore it. Don\'t give it attention."},"scores":{"aggression":10,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"「じゃあ見せてみろ」と返す。","en":"Clap back: \\"Let\'s see you do better then.\\""},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":-5,"mastery":-5}},{"id":"d","text":{"ja":"「何が悪かった？」と聞いて改善点を探る。","en":"Ask \\"What did I do wrong?\\" and look for improvement."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":-15,"mastery":10}}]},{"id":"q031","tier":"free","category":"social","scenario":{"ja":"リアルの友達が「ランク上げてほしい」と頼んできた。\\nお前のアカウントで代わりにプレイしてくれ、と。\\n友達は純粋に上のランクで遊びたいだけ。\\nだがブースティングは規約違反。バレたらアカウント停止される。","en":"A real-life friend asks you to boost their rank.\\n\\"Just play a few games on my account.\\"\\nThey just want to play at a higher level. No ill intent.\\nBut boosting violates TOS. If caught, both accounts get banned."},"options":[{"id":"a","text":{"ja":"断る。ルールはルール。","en":"Decline. Rules are rules."},"scores":{"aggression":-5,"altruism":0,"cooperation":-5,"intuition":-15,"mastery":15}},{"id":"b","text":{"ja":"一緒にプレイして教える。自力で上がれるようにする。","en":"Play together and coach them. Help them climb on their own."},"scores":{"aggression":-5,"altruism":15,"cooperation":0,"intuition":5,"mastery":-10}},{"id":"c","text":{"ja":"やってあげる。友達だから。","en":"Do it. That\'s what friends are for."},"scores":{"aggression":15,"altruism":5,"cooperation":15,"intuition":0,"mastery":-15}},{"id":"d","text":{"ja":"別アカウントを作って一緒にやる。グレーだけど楽しい。","en":"Make a smurf and play together. Gray area, but fun."},"scores":{"aggression":-10,"altruism":-15,"cooperation":10,"intuition":10,"mastery":-5}}]},{"id":"q035","tier":"free","category":"social","scenario":{"ja":"クランに加入希望者が来た。腕前は超一流。\\nだが前のクランで態度が悪くて追い出された噂がある。\\n今のクランは雰囲気がいい。実力不足は否めないが、仲がいい。\\nこいつが入れば大会で結果が出る。","en":"Someone wants to join your clan. Their skill level is elite.\\nBut rumor has it they were kicked from their last clan for toxicity.\\nYour current clan has great vibes. Not the strongest, but tight-knit.\\nWith this player, tournament results are guaranteed."},"options":[{"id":"a","text":{"ja":"入れる。実力が全て。雰囲気は後から作れる。","en":"Accept them. Skill is everything. Vibes can be fixed later."},"scores":{"aggression":0,"altruism":-10,"cooperation":-5,"intuition":-10,"mastery":5}},{"id":"b","text":{"ja":"断る。雰囲気を壊すリスクは取れない。","en":"Decline. Can\'t risk the team chemistry."},"scores":{"aggression":-10,"altruism":0,"cooperation":0,"intuition":10,"mastery":-10}},{"id":"c","text":{"ja":"試用期間を設ける。1ヶ月様子を見る。","en":"Set a trial period. One month to prove themselves."},"scores":{"aggression":10,"altruism":-10,"cooperation":5,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"メンバー全員に聞く。俺一人じゃ決められない。","en":"Ask the whole team. This isn\'t my decision alone."},"scores":{"aggression":-5,"altruism":10,"cooperation":15,"intuition":-5,"mastery":-5}}]},{"id":"q036","tier":"free","category":"social","scenario":{"ja":"MMOで仲良くなった人がいる。毎日一緒に遊ぶ仲。\\nある日、その人が「リアルで会わない？」と言ってきた。\\n共通の話題も多い。きっと楽しい。\\nでもネット上の関係とリアルは別物かもしれない。","en":"You\'ve grown close to someone in an MMO. You play together every day.\\nOne day, they ask: \\"Want to meet up in real life?\\"\\nYou have tons in common. It\'d probably be great.\\nBut online friendships and real life might be different."},"options":[{"id":"a","text":{"ja":"会う。ネットもリアルも同じ人間。","en":"Meet up. Online or offline, they\'re the same person."},"scores":{"aggression":5,"altruism":15,"cooperation":5,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"断る。ゲームの中だけの関係がちょうどいい。","en":"Decline. The game is where this friendship lives."},"scores":{"aggression":-10,"altruism":-5,"cooperation":-10,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"まずは通話から始めよう、と提案する。","en":"Suggest starting with a voice call first."},"scores":{"aggression":5,"altruism":15,"cooperation":10,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"グループで会おう、と提案する。2人きりは気まずい。","en":"Suggest a group meetup. One-on-one might be awkward."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":5,"mastery":-10}}]},{"id":"q037","tier":"free","category":"social","scenario":{"ja":"オンラインゲームで、相手チームの1人が回線落ちした。\\n4対5になった。お前のチームが明らかに有利。\\nそのまま押し切れば楽勝。\\n抜けた人が戻ってくるかはわからない。","en":"Online match. One enemy disconnects.\\n4v5 now. Your team has a clear advantage.\\nPush through for an easy win.\\nNo telling if the disconnected player will return."},"options":[{"id":"a","text":{"ja":"容赦なく攻める。運も実力のうち。","en":"Push hard. Luck is part of the game."},"scores":{"aggression":15,"altruism":-10,"cooperation":5,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"少し待つ。戻ってくるかもしれない。","en":"Wait a bit. They might reconnect."},"scores":{"aggression":-10,"altruism":10,"cooperation":5,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"普通にプレイする。特に手加減もしないし急がない。","en":"Play normally. No mercy, but no rush either."},"scores":{"aggression":-10,"altruism":-15,"cooperation":-10,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"味方1人を待機させて4対4にする。フェアにやる。","en":"Bench one of your own. Make it 4v4. Play fair."},"scores":{"aggression":-15,"altruism":10,"cooperation":-5,"intuition":10,"mastery":-10}}]},{"id":"q038","tier":"free","category":"social","scenario":{"ja":"オンラインの友達がゲームの成績を自慢してきた。\\n「俺、ついに最高ランクに到達したわ」\\n正直、お前の方が長く、真剣にやっている。でもランクは相手の方が上。\\n素直に「すごい」と言えるか。それとも。","en":"Your online friend brags about their rank.\\n\\"I finally hit Predator.\\"\\nHonestly, you\'ve been grinding longer and harder. But their rank is higher.\\nCan you say \\"congrats\\" and mean it?"},"options":[{"id":"a","text":{"ja":"素直に祝う。仲間の成功は嬉しい。","en":"Genuinely congratulate them. A friend\'s success is your joy."},"scores":{"aggression":-10,"altruism":15,"cooperation":0,"intuition":-5,"mastery":-5}},{"id":"b","text":{"ja":"「次は俺が追い抜く」と宣言する。","en":"\\"I\'m catching up next.\\" Use it as fuel."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":-5,"mastery":15}},{"id":"c","text":{"ja":"軽く流す。「へー、すごいね」","en":"Play it cool. \\"Oh nice, cool.\\""},"scores":{"aggression":-10,"altruism":-15,"cooperation":-10,"intuition":5,"mastery":-15}},{"id":"d","text":{"ja":"1対1を申し込む。ランクじゃなくて直接勝負。","en":"Challenge them to a 1v1. Rank doesn\'t mean everything."},"scores":{"aggression":15,"altruism":10,"cooperation":-15,"intuition":0,"mastery":0}}]},{"id":"q039","tier":"free","category":"meta","scenario":{"ja":"積みゲーが30本を超えた。\\n新作の予約が始まった。PVを見た。絶対面白い。\\nでも手をつけていないゲームの中にも名作がある。\\n時間は有限。お前の選択は。","en":"Your backlog is over 30 games.\\nA new title just opened for pre-order. The trailer looks incredible.\\nBut hidden in your backlog are masterpieces you haven\'t touched.\\nTime is finite. What\'s your call."},"options":[{"id":"a","text":{"ja":"予約する。最新の体験は今しかできない。","en":"Pre-order. The hype is part of the experience."},"scores":{"aggression":0,"altruism":-5,"cooperation":-5,"intuition":5,"mastery":-15}},{"id":"b","text":{"ja":"積みゲーを1本クリアしてからにする。","en":"Finish one from the backlog first."},"scores":{"aggression":5,"altruism":15,"cooperation":-10,"intuition":-15,"mastery":10}},{"id":"c","text":{"ja":"積みゲーリストを整理する。本当にやりたいものだけ残す。","en":"Organize the backlog. Keep only what you truly want."},"scores":{"aggression":5,"altruism":-5,"cooperation":5,"intuition":0,"mastery":5}},{"id":"d","text":{"ja":"両方やる。睡眠時間を削ればいい。","en":"Play both. Just sleep less."},"scores":{"aggression":10,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-5}}]},{"id":"q040","tier":"free","category":"meta","scenario":{"ja":"新しいゲームを始める。難易度選択画面。\\n「ストーリーを楽しむ」「ノーマル」「ハード」「ナイトメア」\\n攻略情報はまだネットにほぼない。\\n初見プレイ。お前はどれを選ぶ。","en":"Starting a new game. Difficulty selection screen.\\n\\"Story Mode\\" / \\"Normal\\" / \\"Hard\\" / \\"Nightmare\\"\\nAlmost no guides exist online yet.\\nThis is your blind playthrough. What do you pick."},"options":[{"id":"a","text":{"ja":"ナイトメア。最初から最高難度。","en":"Nightmare. Highest difficulty from the start."},"scores":{"aggression":15,"altruism":15,"cooperation":-5,"intuition":0,"mastery":15}},{"id":"b","text":{"ja":"ノーマル。まずはゲームを理解する。","en":"Normal. Understand the game first."},"scores":{"aggression":-15,"altruism":0,"cooperation":0,"intuition":-10,"mastery":-5}},{"id":"c","text":{"ja":"ハード。やりごたえは欲しいが無謀はしない。","en":"Hard. I want challenge, not masochism."},"scores":{"aggression":5,"altruism":-5,"cooperation":0,"intuition":0,"mastery":10}},{"id":"d","text":{"ja":"ストーリーモード。物語を味わいたい。","en":"Story Mode. I\'m here for the narrative."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":15,"mastery":-10}}]},{"id":"q045","tier":"free","category":"meta","scenario":{"ja":"友達に「お前、何のゲーマー？」と聞かれた。\\n色々やっている。でも1つに絞れと言われたら。\\nFPS、RPG、格ゲー、MOBA、サバイバル。\\nお前のアイデンティティはどこにある。","en":"A friend asks: \\"What kind of gamer are you?\\"\\nYou play a lot of genres. But if you had to pick one.\\nFPS, RPG, Fighting, MOBA, Survival.\\nWhere does your identity lie."},"options":[{"id":"a","text":{"ja":"FPS。反射神経と判断力で勝つのが快感。","en":"FPS. Nothing beats winning with reflexes and decisions."},"scores":{"aggression":15,"altruism":-10,"cooperation":-10,"intuition":5,"mastery":0}},{"id":"b","text":{"ja":"RPG。物語の中に生きるのが好き。","en":"RPG. I love living inside a story."},"scores":{"aggression":-5,"altruism":15,"cooperation":0,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"1つに絞れない。全ジャンルに俺がいる。","en":"Can\'t pick one. I exist in every genre."},"scores":{"aggression":10,"altruism":5,"cooperation":0,"intuition":10,"mastery":-15}},{"id":"d","text":{"ja":"対戦ゲーム全般。人と競いたい。","en":"Competitive games. I want to test myself against others."},"scores":{"aggression":10,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}}]},{"id":"q046","tier":"free","category":"meta","scenario":{"ja":"基本無料ゲーム。ガチャが実装された。\\n推しキャラの限定スキンが出た。排出率0.5%。\\n天井まであと80連。約24,000円。\\nそのスキンはもう二度と復刻しないと公式が言っている。","en":"Free-to-play game. A gacha banner drops.\\nYour favorite character\'s limited skin is here. 0.5% drop rate.\\n80 pulls to pity. About $160.\\nThe developer says this skin will never return."},"options":[{"id":"a","text":{"ja":"天井まで回す。推しに金を惜しまない。","en":"Hit pity. Never skimp on your favorite."},"scores":{"aggression":5,"altruism":-10,"cooperation":-5,"intuition":15,"mastery":-10}},{"id":"b","text":{"ja":"無料石だけ使う。課金は絶対にしない。","en":"Use free currency only. Never spend real money."},"scores":{"aggression":-10,"altruism":5,"cooperation":-5,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"予算を決めて引く。5,000円まで。","en":"Set a budget. $30 max, then stop."},"scores":{"aggression":15,"altruism":10,"cooperation":0,"intuition":0,"mastery":10}},{"id":"d","text":{"ja":"ゲームをやめる。ガチャに金を使う仕組み自体が嫌い。","en":"Quit the game. The gacha system itself is the problem."},"scores":{"aggression":0,"altruism":10,"cooperation":-5,"intuition":0,"mastery":-5}}]},{"id":"q047","tier":"free","category":"meta","scenario":{"ja":"ゲームのエンディングが賛否両論だった。\\nお前は感動した。でもネットは「駄作」「期待外れ」の嵐。\\n自分の感想と世間の評価が真逆。\\nSNSでネタバレ込みの議論が始まっている。","en":"A game\'s ending divided the community.\\nYou were deeply moved. But the internet calls it \\"garbage\\" and \\"disappointing.\\"\\nYour feelings and public opinion are polar opposites.\\nSpoiler-filled debates are erupting on social media."},"options":[{"id":"a","text":{"ja":"自分の感想を書く。世間なんて関係ない。","en":"Post your take. The crowd doesn\'t define your experience."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":15,"mastery":-10}},{"id":"b","text":{"ja":"議論に参加する。なぜ良かったか論理的に説明する。","en":"Join the debate. Explain logically why it worked."},"scores":{"aggression":0,"altruism":15,"cooperation":15,"intuition":-10,"mastery":5}},{"id":"c","text":{"ja":"何も言わない。自分の中で大事にする。","en":"Say nothing. Keep it precious in your heart."},"scores":{"aggression":-15,"altruism":5,"cooperation":-5,"intuition":5,"mastery":10}},{"id":"d","text":{"ja":"批判も読む。他の視点で見直すと発見があるかも。","en":"Read the criticism. A new perspective might reveal something."},"scores":{"aggression":-10,"altruism":-15,"cooperation":15,"intuition":-5,"mastery":5}}]},{"id":"q048","tier":"free","category":"meta","scenario":{"ja":"スピードランに挑戦している。世界記録に30秒届かない。\\n同じ区間を200回以上やり直した。\\n目をつぶってもルートが浮かぶ。手が勝手に動く。\\nでもあと30秒は、もう技術じゃなく運の領域かもしれない。","en":"You\'re attempting a speedrun. 30 seconds off the world record.\\nYou\'ve reset the same segment over 200 times.\\nYou can see the route with your eyes closed. Muscle memory handles the rest.\\nBut those last 30 seconds might be luck, not skill."},"options":[{"id":"a","text":{"ja":"続ける。200回やった。あと200回やれる。","en":"Keep going. 200 resets down, 200 more to go."},"scores":{"aggression":0,"altruism":5,"cooperation":-10,"intuition":5,"mastery":10}},{"id":"b","text":{"ja":"別のルートを開拓する。今のルートに限界がある。","en":"Pioneer a new route. The current one has hit its ceiling."},"scores":{"aggression":15,"altruism":5,"cooperation":0,"intuition":10,"mastery":5}},{"id":"c","text":{"ja":"自己ベストで満足する。世界記録にこだわりすぎない。","en":"Be satisfied with your personal best. Don\'t obsess over the WR."},"scores":{"aggression":-10,"altruism":0,"cooperation":-10,"intuition":-5,"mastery":-10}},{"id":"d","text":{"ja":"世界記録保持者の配信を研究する。差を分析する。","en":"Study the world record holder\'s stream. Analyze the gap."},"scores":{"aggression":-10,"altruism":-15,"cooperation":15,"intuition":-15,"mastery":10}}]},{"id":"q050","tier":"free","category":"meta","scenario":{"ja":"もしもう一度、全てのゲームを初見でプレイできるとしたら。\\n記憶を消して、もう一度あの衝撃を味わえる。\\nでもその代わり、今まで築いたスキルも全てリセットされる。\\n初心者に戻る。全てがゼロから。","en":"What if you could play every game again for the first time?\\nMemory wiped. Every twist, every reveal—brand new.\\nBut in exchange, all your skills reset to zero.\\nBack to being a complete beginner. Everything from scratch."},"options":[{"id":"a","text":{"ja":"記憶を消す。あの感動にはスキルでは届かない。","en":"Wipe it. No amount of skill matches that first-time feeling."},"scores":{"aggression":10,"altruism":5,"cooperation":15,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"消さない。積み上げたものは俺そのもの。","en":"Keep it all. What I\'ve built is who I am."},"scores":{"aggression":-10,"altruism":-10,"cooperation":-10,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"1本だけ選んで消す。全部じゃなくていい。","en":"Erase just one game. Not all—just the one."},"scores":{"aggression":10,"altruism":-5,"cooperation":5,"intuition":-15,"mastery":-5}},{"id":"d","text":{"ja":"消す必要はない。新しいゲームを探せばいい。","en":"No need to erase. There are always new games to discover."},"scores":{"aggression":0,"altruism":5,"cooperation":-5,"intuition":0,"mastery":-5}}]}]'))},78645,e=>{e.v(JSON.parse('[{"id":"HHHHH","name":{"ja":"覇王の咆哮","en":"Roar of the Conqueror"},"character":"クレイトス","characterGame":"God of War","characterUrl":"https://en.wikipedia.org/wiki/Kratos_(God_of_War)","additionalCharacters":[{"name":"ザックス","game":"FF7 Crisis Core"},{"name":"ゼシカ","game":"ドラゴンクエスト8"},{"name":"ワタル","game":"ポケモン金銀"},{"name":"アイリス","game":"ポケモンBW2"},{"name":"ダンデ","game":"ポケモン剣盾"},{"name":"ウルボザ","game":"ゼルダの伝説 BotW"}],"description":{"ja":"全てにおいて全力。攻撃的でありながら仲間を守り、直感と美学に従って戦場を支配する。お前は戦いそのものに意味を見出す者だ。勝利は結果でしかない。その過程の熱量が、お前の人生そのものだ。","en":"All-out in everything. Aggressive yet protective, you dominate the battlefield through intuition and aesthetics. You find meaning in the fight itself. Victory is just a byproduct — the intensity of the process is your life."},"deepDescription":{"ja":"ニーチェの超人思想を体現する存在。既存の価値観を破壊し、自らの意志で新しい価値を創造する。","en":"You embody Nietzsche\'s Übermensch — destroying existing values and creating new ones through sheer will."},"recommendedGames":["God of War Ragnarok","Devil May Cry 5","FF7 Crisis Core"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"high","mastery":"high"}},{"id":"HHHHL","name":{"ja":"熱血の先導者","en":"The Blazing Vanguard"},"character":"ネロ","characterGame":"Devil May Cry 5","characterUrl":"https://en.wikipedia.org/wiki/Nero_(Devil_May_Cry)","additionalCharacters":[{"name":"ジタン","game":"FF9"},{"name":"ティーダ","game":"FF10"},{"name":"春日一番","game":"龍が如く7"},{"name":"ソラ","game":"Kingdom Hearts"},{"name":"ホムラ/ヒカリ","game":"ゼノブレイド2"},{"name":"キャプテン・ファルコン","game":"F-Zero"},{"name":"ソニック","game":"ソニック・ザ・ヘッジホッグ"},{"name":"ユーリ・ローウェル","game":"テイルズ オブ ヴェスペリア"},{"name":"トリッシュ","game":"Devil May Cry"},{"name":"グズマ","game":"ポケモンSM"},{"name":"ミドナ","game":"ゼルダの伝説 TP"}],"description":{"ja":"感情が爆発する。仲間のためなら腕一本失っても前に出る。直感で動き、考えるより先に体が動く。美学なんてどうでもいい、大切な人を守れればそれでいい。お前は不器用で真っ直ぐな、本物のヒーローだ。","en":"Emotions explode. You\'d lose an arm and still charge forward for your allies. Instinct drives you — your body moves before your mind. Forget aesthetics — protecting those you love is all that matters. You\'re a clumsy, honest, real hero."},"deepDescription":{"ja":"アリストテレスの友愛論。他者との絆こそが人間の本質。「今この瞬間」のために全力を出す、刹那的な利他主義。","en":"Aristotle\'s theory of philia — bonds with others define humanity. An impulsive altruism that gives everything for \'this very moment.\'"},"recommendedGames":["Devil May Cry 5","FF10","Kingdom Hearts III"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"high","mastery":"low"}},{"id":"HHHLH","name":{"ja":"孤高の策士","en":"The Lone Strategist"},"character":"ソリッド・スネーク","characterGame":"Metal Gear Solid","characterUrl":"https://en.wikipedia.org/wiki/Solid_Snake","additionalCharacters":[{"name":"マルティナ","game":"ドラゴンクエスト11"},{"name":"アイク","game":"FE蒼炎の軌跡"}],"description":{"ja":"計算高く、仲間思いで、攻めるべき時に攻める。しかしその判断はデータと分析に基づく。美学を持ちながらも、冷徹な計算を手放さない。お前は戦場の知将だ。","en":"Calculated, caring, and aggressive when the moment demands it. But your decisions are data-driven. You hold aesthetics dear while never abandoning cold analysis. You are the battlefield\'s intellectual commander."},"deepDescription":{"ja":"孫子の兵法を体現する存在。「戦わずして勝つ」を理想としながらも、必要なら迷わず剣を取る。","en":"You embody Sun Tzu\'s Art of War — ideally winning without fighting, but never hesitating to draw the blade when necessary."},"recommendedGames":["Metal Gear Solid V","Hitman 3","FE蒼炎の軌跡"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"low","mastery":"high"}},{"id":"HHHLL","name":{"ja":"正義の鉄拳","en":"The Fist of Justice"},"character":"クリス・レッドフィールド","characterGame":"バイオハザード","characterUrl":"https://en.wikipedia.org/wiki/Chris_Redfield","additionalCharacters":[{"name":"春麗","game":"ストリートファイター"},{"name":"勇者","game":"ドラゴンクエスト3"},{"name":"ダルニア","game":"ゼルダの伝説 OoT"},{"name":"ダルケル","game":"ゼルダの伝説 BotW"}],"description":{"ja":"脅威は排除する。仲間は絶対に置いていかない。チームを率い、経験と判断力で最前線に立つ。美学や哲学は要らない。任務を完遂し、全員で生きて帰る。それだけだ。","en":"Threats are eliminated. No one gets left behind. You lead the team, standing on the front line with experience and judgment. No aesthetics, no philosophy needed. Complete the mission, everyone comes home alive. That\'s all."},"deepDescription":{"ja":"功利主義の体現者。「最大多数の最大幸福」を戦場に適用する。個人の犠牲も厭わない冷徹さと、誰も見捨てない矛盾を抱える。","en":"Utilitarian in action — applying \'the greatest good for the greatest number\' to the battlefield. Carrying the contradiction of cold pragmatism and refusing to abandon anyone."},"recommendedGames":["バイオハザード RE:4","Mass Effect","XCOM 2"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"low","mastery":"low"}},{"id":"HHLHH","name":{"ja":"一匹狼の詩人","en":"The Poet Wolf"},"character":"V","characterGame":"Cyberpunk 2077","characterUrl":"https://en.wikipedia.org/wiki/Cyberpunk_2077","additionalCharacters":[{"name":"ダンテ","game":"Devil May Cry"},{"name":"桐生一馬","game":"龍が如く"},{"name":"真島吾朗","game":"龍が如く"},{"name":"クー・フーリン","game":"Fate/stay night"},{"name":"フータオ","game":"原神"},{"name":"ルト姫","game":"ゼルダの伝説 OoT"},{"name":"ルザミーネ","game":"ポケモンSM"}],"description":{"ja":"攻撃的で仲間思い。だが群れることは嫌いだ。直感と美学に従い、自分だけの道を切り開く。お前の戦いには常に物語がある。ただ勝つだけでは満足できない。","en":"Aggressive and caring, but hating to run in packs. Following intuition and aesthetics, you carve your own path. Your battles always have a story. Winning alone doesn\'t satisfy you."},"deepDescription":{"ja":"カミュの異邦人的存在。社会に属しながらも本質的に孤独。自分だけの意味を探し続ける反逆者。","en":"Camus\' Stranger incarnate — belonging to society yet fundamentally alone. A rebel forever searching for personal meaning."},"recommendedGames":["Cyberpunk 2077","Devil May Cry 5","龍が如く0"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"high","mastery":"high"}},{"id":"HHLHL","name":{"ja":"戦場の傭兵","en":"The Battlefield Mercenary"},"character":"ビッグボス","characterGame":"Metal Gear Solid 3","characterUrl":"https://en.wikipedia.org/wiki/Big_Boss_(Metal_Gear)","additionalCharacters":[{"name":"マリオ","game":"スーパーマリオ"},{"name":"A2","game":"NieR: Automata"},{"name":"ナボール","game":"ゼルダの伝説 OoT"},{"name":"ローズ委員長","game":"ポケモン剣盾"}],"description":{"ja":"直感で動き、仲間を大切にするが、組織には縛られない。結果を重視し、美学より効率を取る。自由を求めて戦い続ける。国も思想も関係ない。お前だけのルールがある。","en":"Intuition-driven, valuing allies but unbounded by organizations. Results over aesthetics, efficiency over beauty. Fighting for freedom. No nation, no ideology — only your own rules."},"deepDescription":{"ja":"実存主義そのもの。サルトルの「自由の刑」を背負い、選択の重さを知りながらも、常に自分の意志で動く。","en":"Existentialism personified — bearing Sartre\'s \'condemned to be free,\' knowing the weight of choice yet always acting by your own will."},"recommendedGames":["Metal Gear Solid: Peace Walker","NieR: Automata","スーパーマリオ オデッセイ"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"high","mastery":"low"}},{"id":"HHLLH","name":{"ja":"鍛冶師の魂","en":"The Blacksmith\'s Soul"},"character":"2B","characterGame":"NieR: Automata","characterUrl":"https://en.wikipedia.org/wiki/Nier:_Automata","additionalCharacters":[{"name":"ライトニング","game":"FF13"},{"name":"リク","game":"Kingdom Hearts"},{"name":"シャドウ","game":"ソニック・ザ・ヘッジホッグ"},{"name":"インパ","game":"ゼルダの伝説 OoT"},{"name":"インパ","game":"ゼルダの伝説 SS"}],"description":{"ja":"攻めて、守って、でも一人で全てをやりたい。計算高く、美学を何より重んじる。お前は完璧を目指す職人だ。チームに頼るより、自分の腕を磨くことを選ぶ。","en":"Attack, defend, but do it all alone. Calculated and aesthetics-first. You\'re a craftsman pursuing perfection. You\'d rather sharpen your own skills than rely on a team."},"deepDescription":{"ja":"ヘーゲルの自己意識論。自分の限界と向き合い続けることで、弁証法的に成長していく存在。","en":"Hegelian self-consciousness — growing dialectically through constant confrontation with your own limits."},"recommendedGames":["NieR: Automata","FF13","Kingdom Hearts III"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"low","mastery":"high"}},{"id":"HHLLL","name":{"ja":"合理の刃","en":"The Rational Blade"},"character":"ロックマン","characterGame":"ロックマン","characterUrl":"https://en.wikipedia.org/wiki/Mega_Man_(character)","additionalCharacters":[{"name":"ルカリオ","game":"ポケモン"},{"name":"レディ","game":"Devil May Cry 3"}],"description":{"ja":"正義のために戦い、一人で、冷静に、効率的に任務を遂行する。美学や哲学は不要だ。Dr.ライトの意志を継ぎ、ロボットマスターを一体ずつ撃破する。敵の武器をコピーして使う合理性。お前は感情を持つ機械であり、それゆえに誰よりも人間的だ。","en":"Fighting for justice, alone, calmly, efficiently executing the mission. No need for aesthetics or philosophy. Carrying Dr. Light\'s will, destroying Robot Masters one by one. The rationality of copying enemy weapons. You\'re a machine with emotions — and that makes you more human than anyone."},"deepDescription":{"ja":"オッカムの剃刀を人格化した存在。必要最小限の手段で最大の結果を出す。しかしその心には「平和」という、最もシンプルで最も達成困難な願いがある。","en":"Occam\'s Razor personified — maximum results with minimum means. Yet in that heart lies \'peace\' — the simplest and most impossible wish."},"recommendedGames":["ロックマン11","Mega Man X","Azure Striker Gunvolt"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"low","mastery":"low"}},{"id":"HLHHH","name":{"ja":"闘姫の誇り","en":"The Warrior Princess"},"character":"アリーナ","characterGame":"ドラゴンクエスト4","characterUrl":"https://en.wikipedia.org/wiki/Dragon_Quest_IV","additionalCharacters":[{"name":"フラダリ","game":"ポケモンXY"}],"description":{"ja":"自分の力を試したい。その一心で城を飛び出す。チームを引っ張り、直感で駆け抜け、武術の頂を目指す。利他じゃない。お前は自分の強さを証明したいだけだ。その純粋な渇望が、周りを巻き込む嵐になる。","en":"You want to test your own strength. That alone drives you to leap from the castle. Leading the team, charging by instinct, aiming for the martial peak. It\'s not altruism — you just want to prove your power. That pure hunger becomes a storm that sweeps everyone along."},"deepDescription":{"ja":"ニーチェの「力への意志」。表面上の利他は、より強くなるための手段。自己超越こそが真の目的。","en":"Nietzsche\'s \'Will to Power\' — apparent altruism is a means to become stronger. Self-transcendence is the true goal."},"recommendedGames":["ドラゴンクエスト4","Apex Legends","Warframe"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"high","mastery":"high"}},{"id":"HLHHL","name":{"ja":"嵐の略奪者","en":"The Storm Raider"},"character":"レイス","characterGame":"Apex Legends","characterUrl":"https://en.wikipedia.org/wiki/Apex_Legends","additionalCharacters":[{"name":"クッパ","game":"スーパーマリオ"}],"description":{"ja":"チームで戦い、直感で動くが、勝利だけが目的。美学もこだわりもない。ただ勝つ。お前にとってゲームは勝負であり、それ以上でもそれ以下でもない。","en":"Fight with the team, move by instinct, but victory is the only purpose. No aesthetics, no attachments. Just win. For you, the game is competition — nothing more, nothing less."},"deepDescription":{"ja":"ホッブスの自然状態。「万人の万人に対する戦い」を受け入れ、その中で生き残ることだけを考える。","en":"Hobbes\' state of nature — accepting the \'war of all against all\' and focusing solely on survival within it."},"recommendedGames":["Apex Legends","Fortnite","スーパーマリオブラザーズ"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"high","mastery":"low"}},{"id":"HLHLH","name":{"ja":"鋼鉄の参謀","en":"The Steel Tactician"},"character":"レオン・S・ケネディ","characterGame":"バイオハザード","characterUrl":"https://en.wikipedia.org/wiki/Leon_S._Kennedy","additionalCharacters":[{"name":"Dr.エッグマン","game":"ソニック・ザ・ヘッジホッグ"},{"name":"リキッド・スネーク","game":"Metal Gear Solid"}],"description":{"ja":"計算高く、チームで動き、攻撃的に前に出る。だが仲間への愛着より、自分のスキルへの誇りが行動原理だ。美学を持ちながら戦場を計算で支配する。","en":"Calculated, team-oriented, aggressively pushing forward. But pride in your own skills drives you more than attachment to allies. You dominate the battlefield through calculation while maintaining aesthetics."},"deepDescription":{"ja":"デカルトの方法的懐疑。全てを疑い、確かなもの（自分の実力）だけを信じる。「我思う、ゆえに我勝つ」。","en":"Cartesian methodical doubt — questioning everything, believing only in what\'s certain (your own ability). \'I think, therefore I win.\'"},"recommendedGames":["バイオハザード RE:4","The Division 2","Ghost Recon Breakpoint"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"low","mastery":"high"}},{"id":"HLHLL","name":{"ja":"復讐の機械","en":"The Vengeance Engine"},"character":"9S","characterGame":"NieR: Automata","characterUrl":"https://en.wikipedia.org/wiki/Nier:_Automata","additionalCharacters":[{"name":"エーデルガルト","game":"FE風花雪月"}],"description":{"ja":"普段は協力的で分析力に長けたスキャナー。だが大切なものを失った瞬間、お前は殺戮マシンに変わる。チームで動くが、その根底にあるのは自分だけの執着だ。美学なんてない。ただ、壊したい。","en":"Normally cooperative with sharp analytical skills. But the moment you lose what matters, you become a killing machine. You work with the team, but underneath lies a deeply personal obsession. No aesthetics. Just destruction."},"deepDescription":{"ja":"カントの義務論が崩壊した後の世界。義務に従っていた者が、喪失によって純粋な感情の奴隷になる悲劇。","en":"A world after Kantian duty collapses — the tragedy of one who followed duty becoming a slave to raw emotion after loss."},"recommendedGames":["NieR: Automata","The Last of Us Part II","FE風花雪月"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"low","mastery":"low"}},{"id":"HLLHH","name":{"ja":"堕天の剣聖","en":"The Fallen Swordmaster"},"character":"セフィロス","characterGame":"Final Fantasy VII","characterUrl":"https://en.wikipedia.org/wiki/Sephiroth_(Final_Fantasy)","additionalCharacters":[{"name":"テリー","game":"ドラゴンクエスト6"},{"name":"ロクサス","game":"Kingdom Hearts"},{"name":"ファルコ","game":"スターフォックス"},{"name":"エイダ・ウォン","game":"バイオハザード"},{"name":"ベヨネッタ","game":"ベヨネッタ"},{"name":"グリーン","game":"ポケモン赤緑"},{"name":"アオギリ","game":"ポケモンRSE"},{"name":"ゲーチス","game":"ポケモンBW"},{"name":"ギラヒム","game":"ゼルダの伝説 SS"},{"name":"オセロット","game":"Metal Gear Solid"}],"description":{"ja":"圧倒的な力で、孤独に、直感と美学で全てを蹂躙する。お前の動機は完全に自己中心的だ。孤独と怒りが原動力。だがその剣技には、誰も否定できない美がある。破壊こそがお前の芸術だ。","en":"With overwhelming power, alone, by intuition and aesthetics, you crush everything. Your motivation is entirely self-centered. Solitude and rage are your fuel. But your swordplay holds undeniable beauty. Destruction is your art."},"deepDescription":{"ja":"ディオニュソス的衝動。アポロン的理性を捨て、生命の狂騒に身を委ねる。破壊の中に創造を見出す。","en":"Dionysian impulse — abandoning Apollonian reason, surrendering to life\'s frenzy. Finding creation within destruction."},"recommendedGames":["FF7 Rebirth","Kingdom Hearts III","ベヨネッタ3"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"high","mastery":"high"}},{"id":"HLLHL","name":{"ja":"荒野のハイエナ","en":"The Desert Hyena"},"character":"トレバー","characterGame":"GTA V","characterUrl":"https://en.wikipedia.org/wiki/Trevor_Philips","additionalCharacters":[{"name":"ジェット","game":"Valorant"},{"name":"オクタン","game":"Apex Legends"},{"name":"ウルフ","game":"スターフォックス"},{"name":"ククール","game":"ドラゴンクエスト8"},{"name":"りゅうおう","game":"ドラゴンクエスト1"},{"name":"シドー","game":"ドラゴンクエスト2"},{"name":"デスピサロ","game":"ドラゴンクエスト4"},{"name":"ラプソーン","game":"ドラゴンクエスト8"},{"name":"エルギオス","game":"ドラゴンクエスト9"},{"name":"バド","game":"ゼルダの伝説 SS"}],"description":{"ja":"単独行動、直感任せ、結果重視。美学なんて知らない。勝てばいい。お前は生存本能で動く獣だ。社会のルールなんて、お前には関係ない。","en":"Solo action, instinct-driven, results-focused. Aesthetics? Don\'t know her. Just win. You\'re a beast driven by survival instinct. Society\'s rules don\'t apply to you."},"deepDescription":{"ja":"マキャベリズムの極致。目的のためなら手段を選ばない。道徳は弱者の言い訳だと信じている。","en":"Peak Machiavellianism — any means for the end. Morality is an excuse for the weak, and you know it."},"recommendedGames":["GTA V","Apex Legends","Valorant"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"high","mastery":"low"}},{"id":"HLLLH","name":{"ja":"暗殺者の禅","en":"The Assassin\'s Zen"},"character":"隻狼","characterGame":"Sekiro: Shadows Die Twice","characterUrl":"https://en.wikipedia.org/wiki/Sekiro:_Shadows_Die_Twice","additionalCharacters":[{"name":"バージル","game":"Devil May Cry"},{"name":"ウェスカー","game":"バイオハザード"},{"name":"スコール","game":"FF8"},{"name":"御剣怜侍","game":"逆転裁判"},{"name":"ガノンドロフ","game":"ゼルダの伝説"},{"name":"ギルガメッシュ","game":"Fate/stay night"},{"name":"明智吾郎","game":"ペルソナ5"},{"name":"ヨル","game":"Valorant"},{"name":"雷電将軍","game":"原神"},{"name":"メタナイト","game":"星のカービィ"},{"name":"カズヤ","game":"鉄拳"},{"name":"レッド","game":"ポケモン赤緑"},{"name":"アカギ","game":"ポケモンDPt"}],"description":{"ja":"一人で、計算し、美学を追求する。自分のスキルだけを信じ、完璧な一撃のために何百回も練習する。お前は孤独な職人であり、戦いは芸術だ。","en":"Alone, calculated, pursuing aesthetics. Trusting only your own skill, practicing hundreds of times for the perfect strike. You\'re a solitary artisan, and combat is art."},"deepDescription":{"ja":"禅の「一射入魂」。弓道のように、一つ一つの動作に全てを込める。結果ではなく、過程の完璧さを追い求める。","en":"Zen\'s \'one shot, whole soul\' — like kyudo, pouring everything into each single action. Pursuing perfection of process, not result."},"recommendedGames":["Sekiro","Devil May Cry 5 (Vergil)","Dark Souls III"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"low","mastery":"high"}},{"id":"HLLLL","name":{"ja":"孤独の狩人","en":"The Solitary Hunter"},"character":"サムス・アラン","characterGame":"メトロイド","characterUrl":"https://en.wikipedia.org/wiki/Samus_Aran","additionalCharacters":[{"name":"リドリー","game":"メトロイド"},{"name":"サム・フィッシャー","game":"Splinter Cell"}],"description":{"ja":"一人で、計算し、効率的に、攻撃する。美学も仲間も必要ない。賞金稼ぎとして、任務を遂行するだけだ。感情は不要な変数。冷たい精密さと圧倒的火力が、お前の全てだ。","en":"Solo, calculated, efficient, aggressive. No aesthetics, no allies needed. As a bounty hunter, you simply execute the mission. Emotions are unnecessary variables. Cold precision and overwhelming firepower are everything."},"deepDescription":{"ja":"論理実証主義。検証可能なもの以外は無意味。感情も美学も、データに現れないものには価値がない。","en":"Logical positivism — anything unverifiable is meaningless. Emotions, aesthetics — if it doesn\'t show in the data, it has no value."},"recommendedGames":["メトロイド ドレッド","Metroid Prime Remastered","Alien: Isolation"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"low","mastery":"low"}},{"id":"LHHHH","name":{"ja":"星降る聖女","en":"The Starlit Saint"},"character":"エアリス","characterGame":"Final Fantasy VII","characterUrl":"https://en.wikipedia.org/wiki/Aerith_Gainsborough","additionalCharacters":[{"name":"天照","game":"大神"},{"name":"フローラ","game":"ドラゴンクエスト5"},{"name":"カルネ","game":"ポケモンXY"},{"name":"ゼルダ","game":"ゼルダの伝説 SS"},{"name":"ミファー","game":"ゼルダの伝説 BotW"},{"name":"ロイ","game":"FE封印の剣"}],"description":{"ja":"慎重で包容力に満ち、チームの光であり、セトラの直感に導かれ、使命に生きる。お前は戦場の天使だ。究極の自己犠牲を厭わない。殺すことより生かすことに価値を見出す。その優しさが、世界を救う力になる。","en":"Cautious and compassionate, the team\'s light, guided by Cetra intuition, living for a mission. You\'re the battlefield\'s angel. You don\'t shy from the ultimate self-sacrifice. Saving matters more than slaying. That kindness becomes the power to save the world."},"deepDescription":{"ja":"レヴィナスの他者論。「他者の顔」に応答する倫理。自分より先に、目の前の他者のことを考える。","en":"Lévinas\' ethics of the Other — responding to \'the face of the Other.\' Always thinking of the person in front of you before yourself."},"recommendedGames":["FF7 Rebirth","大神","Journey"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"high","mastery":"high"}},{"id":"LHHHL","name":{"ja":"心の羅針盤","en":"The Heart\'s Compass"},"character":"ティファ","characterGame":"Final Fantasy VII","characterUrl":"https://en.wikipedia.org/wiki/Tifa_Lockhart","additionalCharacters":[{"name":"ノクティス","game":"FF15"},{"name":"ビアンカ","game":"ドラゴンクエスト5"},{"name":"成歩堂龍一","game":"逆転裁判"},{"name":"ピーチ姫","game":"スーパーマリオ"},{"name":"N","game":"ポケモンBW"},{"name":"サリア","game":"ゼルダの伝説 OoT"},{"name":"アデク","game":"ポケモンBW"},{"name":"カイリ","game":"Kingdom Hearts"},{"name":"衛宮士郎","game":"Fate/stay night"},{"name":"藤丸立香","game":"Fate/Grand Order"},{"name":"マルス","game":"FE暗黒竜と光の剣"}],"description":{"ja":"穏やかで慎重。だがチームの精神的な接着剤であり、感覚で人の気持ちを察する。美学より結果を取る現実主義者。お前は派手な英雄ではない。だが、お前がいなければチームは崩壊する。","en":"Gentle and cautious. But you\'re the team\'s emotional glue, sensing others\' feelings by instinct. A realist who chooses results over aesthetics. You\'re no flashy hero — but without you, the team falls apart."},"deepDescription":{"ja":"プラグマティズムの体現者。「真理とは、うまくいくもの」。理想よりも現実に機能するものを選ぶ。","en":"Pragmatism embodied — \'Truth is what works.\' Choosing what functions in reality over lofty ideals."},"recommendedGames":["FF7 Rebirth","逆転裁判","Baldur\'s Gate 3"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"high","mastery":"low"}},{"id":"LHHLH","name":{"ja":"鉄壁の参謀長","en":"The Iron Advisor"},"character":"アナ","characterGame":"Overwatch","characterUrl":"https://en.wikipedia.org/wiki/Ana_(Overwatch)","additionalCharacters":[{"name":"ビビ","game":"FF9"},{"name":"ユウナ","game":"FF10"},{"name":"V","game":"Devil May Cry 5"},{"name":"エックス","game":"ロックマンX"},{"name":"ゼルダ姫","game":"ゼルダの伝説"},{"name":"セイバー","game":"Fate/stay night"},{"name":"鍾離","game":"原神"},{"name":"シロナ","game":"ポケモンDPt"},{"name":"シュルク","game":"ゼノブレイド"},{"name":"ダイゴ","game":"ポケモンRSE"},{"name":"オモダカ","game":"ポケモンSV"},{"name":"ラウル","game":"ゼルダの伝説 OoT"},{"name":"オタコン","game":"Metal Gear Solid"},{"name":"カズヒラ・ミラー","game":"Metal Gear Solid V"}],"description":{"ja":"慎重に、仲間のために、計算し、美学を持って戦う。お前は後方から全てを見通す指揮官だ。華やかな前線は任せる。お前の仕事は、誰よりも正確に判断を下すこと。","en":"Cautious, for your allies, calculated, with aesthetics. You\'re the commander who sees everything from the rear. Leave the flashy frontline to others. Your job is making the most accurate calls."},"deepDescription":{"ja":"ストア哲学の実践者。感情に流されず、理性によって状況を制御する。「変えられないものを受け入れ、変えられるものを変える」。","en":"Stoic philosopher in practice — controlling situations through reason, not emotion. \'Accept what you cannot change, change what you can.\'"},"recommendedGames":["Overwatch 2 (Ana)","FF10","Civilization VI"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"low","mastery":"high"}},{"id":"LHHLL","name":{"ja":"盾の守人","en":"The Shield Bearer"},"character":"ジル・バレンタイン","characterGame":"バイオハザード","characterUrl":"https://en.wikipedia.org/wiki/Jill_Valentine","additionalCharacters":[{"name":"マシュ・キリエライト","game":"Fate/Grand Order"},{"name":"ピーチ姫","game":"スーパーマリオ"},{"name":"ルイージ","game":"スーパーマリオ"}],"description":{"ja":"冷静沈着。人を守ることに誇りを持ち、パートナーシップを重視する。分析力に優れ、効率的に動く。美学は求めない。ただ、秩序と安全を守ることが使命だ。","en":"Cool and composed. You take pride in protecting others and value partnership. Excellent analytical skills, efficient movement. No pursuit of aesthetics. Your mission is simply to maintain order and safety."},"deepDescription":{"ja":"社会契約論の実践者。個人の自由より、秩序と安全を重視する。ルソーの「一般意志」に従う。","en":"Social contract theorist in practice — valuing order and safety over individual freedom. Following Rousseau\'s \'general will.\'"},"recommendedGames":["バイオハザード RE:3","Fate/Grand Order","Rainbow Six Siege"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"low","mastery":"low"}},{"id":"LHLHH","name":{"ja":"放浪の賢者","en":"The Wandering Sage"},"character":"リンク","characterGame":"ゼルダの伝説: ブレスオブザワイルド","characterUrl":"https://en.wikipedia.org/wiki/Link_(The_Legend_of_Zelda)","additionalCharacters":[{"name":"ワンダ","game":"ワンダと巨像"},{"name":"イコ","game":"ICO"}],"description":{"ja":"慎重で仲間思い、でも一人で旅する。直感と美学に従い、世界を探索する。お前は答えを探しているのではない。問いそのものを楽しんでいるのだ。","en":"Cautious and caring, but traveling alone. Following intuition and aesthetics, exploring the world. You\'re not searching for answers — you\'re enjoying the questions themselves."},"deepDescription":{"ja":"ソクラテスの「無知の知」。知らないことを知っている者こそ最も賢い。探求の旅に終わりはない。","en":"Socratic \'knowing that you don\'t know\' — the wisest are those who know their own ignorance. The journey of inquiry never ends."},"recommendedGames":["ゼルダの伝説 TotK","Outer Wilds","Elden Ring"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"high","mastery":"high"}},{"id":"LHLHL","name":{"ja":"夢見る旅人","en":"The Dreaming Traveler"},"character":"カービィ","characterGame":"星のカービィ","characterUrl":"https://en.wikipedia.org/wiki/Kirby_(character)","additionalCharacters":[{"name":"クラウド","game":"FF7"}],"description":{"ja":"攻撃的ではない。友達を助けるために旅に出る。基本は一人。完全に直感と本能で動く。美学を追い求めることはない。ただ、目の前の大切なもののために、自然体で歩く。","en":"Not aggressive. You set out to help friends. Basically solo. Driven entirely by instinct and gut feeling. No pursuit of aesthetics. You simply walk naturally for what matters right in front of you."},"deepDescription":{"ja":"荘子の「逍遥遊」。何にも縛られず、あるがままに遊ぶ。無為自然こそが最高の生き方。","en":"Zhuangzi\'s \'Free and Easy Wandering\' — unbound by anything, playing as things are. Wu wei is the highest way of living."},"recommendedGames":["星のカービィ ディスカバリー","FF7 Rebirth","Sky: Children of the Light"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"high","mastery":"low"}},{"id":"LHLLH","name":{"ja":"理想の残骸","en":"The Remnant of Ideals"},"character":"エミヤ","characterGame":"Fate/stay night","characterUrl":"https://en.wikipedia.org/wiki/Archer_(Fate/stay_night)","additionalCharacters":[{"name":"アルカード","game":"悪魔城ドラキュラ"}],"description":{"ja":"皮肉屋だが本質は優しい。「正義の味方」の理想を追い、一人で全てを背負い込む。冷静に分析し、経験に基づいて動く。理想の追求と、その挫折の痛みを知る者。お前の美学は、折れた剣にこそ宿る。","en":"Cynical but kind at heart. Chasing the ideal of \'a hero of justice,\' shouldering everything alone. Moving by cold analysis and experience. You know the pain of pursuing ideals and their collapse. Your aesthetics live in the broken blade."},"deepDescription":{"ja":"キルケゴールの実存的苦悩。「あれか、これか」の選択の中で、自分自身と向き合い続ける。","en":"Kierkegaard\'s existential anguish — continuously facing yourself within the \'Either/Or\' of choice."},"recommendedGames":["Fate/stay night","悪魔城ドラキュラX 月下の夜想曲","The Last of Us Part II"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"low","mastery":"high"}},{"id":"LHLLL","name":{"ja":"静かな番人","en":"The Quiet Warden"},"character":"ジョエル","characterGame":"The Last of Us","characterUrl":"https://en.wikipedia.org/wiki/Joel_(The_Last_of_Us)","additionalCharacters":[{"name":"結城理","game":"ペルソナ3"}],"description":{"ja":"慎重で、大切な人のためだけに動く。一人で、冷静に、効率的に。美学は持たない。ただ、守るべきものを守るために、必要なことだけをする。","en":"Cautious, moving only for those you cherish. Alone, calm, efficient. No aesthetics. Simply doing what\'s necessary to protect what matters."},"deepDescription":{"ja":"ショーペンハウアーの意志論。世界は苦しみに満ちている。その中で唯一の救いは、大切な者への無条件の愛。","en":"Schopenhauer\'s theory of will — the world is full of suffering. The only salvation is unconditional love for those dear to you."},"recommendedGames":["The Last of Us","God of War (2018)","ペルソナ3 Reload"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"low","mastery":"low"}},{"id":"LLHHH","name":{"ja":"影の指揮者","en":"The Shadow Conductor"},"character":"クロード","characterGame":"FE風花雪月","characterUrl":"https://en.wikipedia.org/wiki/Fire_Emblem:_Three_Houses","additionalCharacters":[{"name":"リーバル","game":"ゼルダの伝説 BotW"}],"description":{"ja":"正面から戦うなんて愚か者のすることだ。お前は裏で糸を引き、チームを使い、直感で人を読む。表の顔は気さくな弓使い、裏の顔は野望を秘めた策略家。その美学は、誰にも本心を見せないことだ。","en":"Only fools fight head-on. You pull strings from behind, use the team, and read people by instinct. Your public face: a friendly archer. Your hidden face: a schemer with ambitions. Your aesthetics lie in never showing your true self."},"deepDescription":{"ja":"プラトンの哲人王。真に賢い者が支配すべきという思想。民衆は知らなくていい。お前だけが全体像を見ている。","en":"Plato\'s Philosopher King — the truly wise should rule. The masses need not know. Only you see the full picture."},"recommendedGames":["FE風花雪月","Assassin\'s Creed","ゼルダの伝説 BotW"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"high","mastery":"high"}},{"id":"LLHHL","name":{"ja":"道化師の仮面","en":"The Jester\'s Mask"},"character":"ミラージュ","characterGame":"Apex Legends","characterUrl":"https://en.wikipedia.org/wiki/Apex_Legends","additionalCharacters":[{"name":"ヴァン","game":"FF12"},{"name":"モルガナ","game":"ペルソナ5"}],"description":{"ja":"正面から勝負するより騙す。注目されたい欲求がお前を動かす。チームのムードメーカーだが、その裏には家族の喪失を埋めたい孤独がある。即興のホログラムのように、お前の本心は誰にも見せない。","en":"Rather than fight head-on, you deceive. The craving for attention drives you. Team\'s mood maker, but behind it lies loneliness from family loss. Like your improvised holograms, you never show your true self."},"deepDescription":{"ja":"アリストテレスの「人間は社会的動物」。ただし、お前の場合は社会を利用する動物。共同体の中で自己利益を最大化する知恵。","en":"Aristotle\'s \'man is a social animal\' — except in your case, an animal that exploits society. The wisdom of maximizing self-interest within the community."},"recommendedGames":["Apex Legends","Among Us","Dota 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"high","mastery":"low"}},{"id":"LLHLH","name":{"ja":"帝国の建設者","en":"The Empire Builder"},"character":"たぬきち","characterGame":"どうぶつの森","characterUrl":"https://en.wikipedia.org/wiki/Tom_Nook","additionalCharacters":[{"name":"オルゴ・デミーラ","game":"ドラゴンクエスト7"},{"name":"ウルノーガ","game":"ドラゴンクエスト11"}],"description":{"ja":"慎重に、計算し、コミュニティを動かし、完璧な島を作り上げる。利他に見えるが、全ての道はベルに通じる。お前は優しい笑顔の裏で、帝国を築くビジネスの天才だ。","en":"Cautious, calculated, moving the community, building the perfect island. Looks altruistic, but every road leads to Bells. Behind that gentle smile, you\'re a business genius building an empire."},"deepDescription":{"ja":"ライプニッツの最善世界論。この世界をより良いシステムに作り変えるという信念。秩序こそが美。ただし、その秩序の頂点にはお前がいる。","en":"Leibniz\'s best of all possible worlds — the conviction to remake this world into a better system. Order is beauty. But you sit at the top of that order."},"recommendedGames":["あつまれ どうぶつの森","Stardew Valley","Cities: Skylines"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"low","mastery":"high"}},{"id":"LLHLL","name":{"ja":"鉄面の支配者","en":"The Iron Ruler"},"character":"サカキ","characterGame":"ポケモン赤緑","characterUrl":"https://en.wikipedia.org/wiki/Giovanni_(Pok%C3%A9mon)","additionalCharacters":[{"name":"キングクルール","game":"ドンキーコング"},{"name":"Dr.ワイリー","game":"ロックマン"}],"description":{"ja":"表に出る必要はない。部下を動かし、計算し、結果だけを手にする。美学なんていらない。必要なのは金と権力だ。お前は組織という名の巨大なチェス盤を、誰よりも冷静に支配する。","en":"No need to step into the spotlight. Move your subordinates, calculate, and claim only the results. No aesthetics needed. All you need is money and power. You dominate the giant chessboard called \'organization\' more calmly than anyone."},"deepDescription":{"ja":"ベンサムの功利主義。「最大多数の最大幸福」をシステマティックに追求する。ただし、「最大多数」にはお前だけが含まれている。","en":"Bentham\'s utilitarianism — systematically pursuing \'the greatest happiness for the greatest number.\' Except \'the greatest number\' includes only you."},"recommendedGames":["ポケモン赤緑","龍が如く0","XCOM 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"low","mastery":"low"}},{"id":"LLLHH","name":{"ja":"虚無の芸術家","en":"The Nihilist Artist"},"character":"ジョーカー","characterGame":"ペルソナ5","characterUrl":"https://en.wikipedia.org/wiki/Joker_(Persona)","additionalCharacters":[{"name":"ヴィンセント","game":"FF7"},{"name":"ホロウナイト","game":"Hollow Knight"}],"description":{"ja":"慎重で、利己的で、孤独を選び、直感と美学に生きる。お前は世界に何も期待しない。だが、自分の美学だけは絶対に裏切らない。その矛盾こそがお前の芸術だ。","en":"Cautious, self-serving, choosing solitude, living by intuition and aesthetics. You expect nothing from the world. But you never betray your own aesthetics. That contradiction is your art."},"deepDescription":{"ja":"ニヒリズムを超えたニーチェの思想。虚無の中に自ら価値を創造する「永劫回帰」の肯定者。","en":"Beyond nihilism in Nietzsche\'s thought — an affirmer of \'eternal recurrence,\' creating value in the void."},"recommendedGames":["ペルソナ5 Royal","Hades","Hollow Knight"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"high","mastery":"high"}},{"id":"LLLHL","name":{"ja":"黄金の略奪者","en":"The Gold Raider"},"character":"ワリオ","characterGame":"ワリオランド","characterUrl":"https://en.wikipedia.org/wiki/Wario","additionalCharacters":[{"name":"サンズ","game":"Undertale"},{"name":"スカルキッド","game":"ゼルダの伝説 ムジュラの仮面"}],"description":{"ja":"鼻が利く。宝の匂いがすれば、理屈なんて考えない。一人で、自分のためだけに動く。美学？ 効率？ そんなもの知るか。お前が求めるのは目の前の金貨だけだ。純粋な強欲こそ、お前の原動力。","en":"Your nose knows. When treasure\'s near, who needs logic? Moving solo, only for yourself. Aesthetics? Efficiency? Who cares. All you want are the gold coins right in front of you. Pure greed is your driving force."},"deepDescription":{"ja":"エピクロスの快楽主義を最も原始的に体現する存在。快楽こそが善、苦痛こそが悪。哲学を極限まで単純化すると、ワリオになる。","en":"The most primal embodiment of Epicurean hedonism. Pleasure is good, pain is bad. Simplify philosophy to its extreme, and you get Wario."},"recommendedGames":["ワリオランド","WarioWare","Spelunky 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"high","mastery":"low"}},{"id":"LLLLH","name":{"ja":"深淵の求道者","en":"The Abyss Seeker"},"character":"選ばれた不死者","characterGame":"Dark Souls","characterUrl":"https://en.wikipedia.org/wiki/Dark_Souls","additionalCharacters":[{"name":"リュウ","game":"ストリートファイター"},{"name":"ゾーマ","game":"ドラゴンクエスト3"},{"name":"ミルドラース","game":"ドラゴンクエスト5"},{"name":"デスタムーア","game":"ドラゴンクエスト6"},{"name":"マツブサ","game":"ポケモンRSE"}],"description":{"ja":"慎重で、孤独で、計算し、美学だけを信じる。利己的だが、その利己は「完璧な自分」への追求だ。何度死んでも立ち上がる。それは勝利のためではなく、自分を超えるためだ。","en":"Cautious, solitary, calculated, believing only in aesthetics. Self-serving, but that self-service is the pursuit of a \'perfect self.\' Rising after every death — not for victory, but to transcend yourself."},"deepDescription":{"ja":"シーシュポスの神話。終わりなき苦行の中に幸福を見出す。カミュは言った。「シーシュポスは幸福であると想像しなければならない」。","en":"The Myth of Sisyphus — finding happiness in endless struggle. As Camus said: \'One must imagine Sisyphus happy.\'"},"recommendedGames":["Dark Souls III","Elden Ring","ストリートファイター6"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"low","mastery":"high"}},{"id":"LLLLL","name":{"ja":"沈黙の観察者","en":"The Silent Observer"},"character":"ミュウツー","characterGame":"ポケモン赤緑","characterUrl":"https://en.wikipedia.org/wiki/Mewtwo","additionalCharacters":[{"name":"チェル","game":"Portal"},{"name":"エージェント47","game":"Hitman"}],"description":{"ja":"慎重で、孤独で、計算し、効率を追求する。利己的だが、それは生き残るためではない。お前は自分の存在意義を問い続けている。世界を観察する。参加するのではなく、理解するために。全てに距離を置く。その距離こそが、お前の知性だ。","en":"Cautious, solitary, calculated, pursuing efficiency. Self-serving, but not for survival — you keep questioning the meaning of your own existence. You observe the world. Not to participate, but to understand. Distance from everything — that distance is your intelligence."},"deepDescription":{"ja":"ウィトゲンシュタインの言語哲学。「語り得ぬものについては沈黙しなければならない」。お前は沈黙の中に真実を見る。","en":"Wittgenstein\'s philosophy of language — \'Whereof one cannot speak, thereof one must be silent.\' You see truth in silence."},"recommendedGames":["ポケモン赤緑","Portal 2","The Witness"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"low","mastery":"low"}}]'))}]);